import base64

import pyotp

from app.config import USERS
from app.models import Reserva

RESERVA = {"sala": "Atlas", "fecha": "2026-10-05T10:00", "duracion_min": 60}


def otp_for(username: str) -> str:
    return pyotp.TOTP(USERS[username]["otp_secret"]).now()


def basic_headers(username: str, password: str, otp: str) -> dict:
    creds = base64.b64encode(f"{username}:{password}".encode()).decode()
    return {"Authorization": f"Basic {creds}", "X-OTP": otp}


def test_export_sin_reservas_devuelve_solo_cabecera(client):
    r = client.get("/export", headers=basic_headers("alice", "alice-pass", otp_for("alice")))
    assert r.status_code == 200
    assert r.headers["content-type"] == "text/csv; charset=utf-8"
    assert r.text.strip().splitlines() == [",".join(Reserva.model_fields)]


def test_export_con_reservas(client, auth):
    client.post("/reservas", json=RESERVA, headers=auth)
    r = client.get("/export", headers=basic_headers("alice", "alice-pass", otp_for("alice")))
    assert r.status_code == 200
    lineas = r.text.strip().splitlines()
    assert lineas[0] == ",".join(Reserva.model_fields)
    assert len(lineas) == 2
    assert "Atlas" in lineas[1]


def test_export_sin_credenciales(client):
    assert client.get("/export").status_code == 401


def test_export_password_incorrecta(client):
    r = client.get("/export", headers=basic_headers("alice", "mal", otp_for("alice")))
    assert r.status_code == 401


def test_export_sin_otp(client):
    creds = base64.b64encode(b"alice:alice-pass").decode()
    r = client.get("/export", headers={"Authorization": f"Basic {creds}"})
    assert r.status_code == 401


def test_export_otp_incorrecto(client):
    r = client.get("/export", headers=basic_headers("alice", "alice-pass", "000000"))
    assert r.status_code == 401

